# Write your MySQL query statement below
select Students.student_id,Students.student_name,Subjects.subject_name, Count(Examinations.subject_name) as attended_exams from Students Join Subjects Left Join Examinations on Students.student_id=Examinations.student_id and Subjects.subject_name = Examinations.subject_name Group by Students.student_id,Subjects.subject_name order by student_id ASC,subject_name ASC;